ee:variables.ee:set-variable:
%dw 2.0
output application/java
var base       = vars.branchBase
// names already taken on the remote (strip the refs/heads/ prefix)
var taken      = (vars.existingRefs default []) map ((r) -> ((r.ref as String) replace /^refs\/heads\// with ""))
// try the base first, then base-1 .. base-50
var candidates = [base] ++ ((1 to 50) map ((n) -> base ++ "-" ++ (n as String)))
---
(candidates filter ((c) -> !(taken contains c)))[0] default (base ++ "-" ++ vars.jobId)

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
    base_tree: vars.changePlan.headSha,
    tree: vars.blobs map ((b) -> {
        path: b.path,
        mode: "100644",
        "type": "blob",
        sha:  b.blobSha
    })
}
